import { CreateNewMenuItemContent } from "@/wab/client/components/menu-builder";
import Select from "@/wab/client/components/widgets/Select";
import {
  DefaultProjectDestinationFormProps,
  PlasmicProjectDestinationForm,
} from "@/wab/client/plasmic/plasmic_kit_dashboard/PlasmicProjectDestinationForm";
import { ApiTeam, ApiWorkspace } from "@/wab/shared/ApiSchema";
import { ensure } from "@/wab/shared/common";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import * as React from "react";

/** An organization the project can move to. */
export interface ProjectDestinationOrg {
  org: ApiTeam;
  needsUpgrade: boolean;
  workspaces: ApiWorkspace[];
}

export type ProjectDestination =
  | { type: "workspace"; org: ApiTeam; workspace: ApiWorkspace }
  | { type: "newWorkspace"; org: ApiTeam; name: string };

export const NEW_WORKSPACE_NAME = "AI Projects";

export interface ProjectDestinationFormProps extends DefaultProjectDestinationFormProps {
  orgs: ProjectDestinationOrg[];
  onSubmit: (destination: ProjectDestination) => void;
  onCancel: () => void;
}

// Workspace select value of the "Create new workspace" option.
const NEW_WORKSPACE_VALUE = "new";

function getDefaultWorkspaceValue(destinationOrg: ProjectDestinationOrg) {
  if (destinationOrg.workspaces.length === 0) {
    return NEW_WORKSPACE_VALUE;
  }
  return destinationOrg.workspaces.length === 1
    ? destinationOrg.workspaces[0].id
    : undefined;
}

function ProjectDestinationForm_(
  props: ProjectDestinationFormProps,
  ref: HTMLElementRefOf<"div">,
) {
  const { orgs, onSubmit, onCancel, ...rest } = props;
  const [selected, setSelected] = React.useState(() =>
    ensure(orgs[0], "Expected an organization to move the project to"),
  );
  const [workspaceValue, setWorkspaceValue] = React.useState(() =>
    getDefaultWorkspaceValue(selected),
  );
  const [newWorkspaceName, setNewWorkspaceName] =
    React.useState(NEW_WORKSPACE_NAME);

  const workspace = selected.workspaces.find((w) => w.id === workspaceValue);
  const isNewWorkspace = workspaceValue === NEW_WORKSPACE_VALUE;
  const name = newWorkspaceName.trim();
  const destination: ProjectDestination | undefined = workspace
    ? { type: "workspace", org: selected.org, workspace }
    : isNewWorkspace && name
      ? { type: "newWorkspace", org: selected.org, name }
      : undefined;

  return (
    <PlasmicProjectDestinationForm
      root={{ ref }}
      {...rest}
      orgSwitcher={{
        props: {
          selectedOrg: selected.org,
          orgs: orgs.map((o) => o.org),
          onSelectOrg: (org) => {
            const picked = ensure(
              orgs.find((o) => o.org.id === org.id),
              "Expected the picked organization in the list",
            );
            if (picked !== selected) {
              setSelected(picked);
              setWorkspaceValue(getDefaultWorkspaceValue(picked));
            }
          },
        },
      }}
      workspaceLabel={{ props: { id: "project-destination-workspace" } }}
      workspaceSelect={{
        props: {
          "aria-labelledby": "project-destination-workspace",
          value: workspaceValue,
          onChange: (v) => setWorkspaceValue(v ?? undefined),
          children: [
            ...selected.workspaces.map((w) => (
              <Select.Option key={w.id} value={w.id}>
                {w.name}
              </Select.Option>
            )),
            <Select.Option
              key={NEW_WORKSPACE_VALUE}
              value={NEW_WORKSPACE_VALUE}
            >
              <CreateNewMenuItemContent entity="workspace" />
            </Select.Option>,
          ],
        },
      }}
      workspaceNameField={isNewWorkspace ? {} : { render: () => null }}
      workspaceNameLabel={{ props: { htmlFor: "project-destination-name" } }}
      workspaceNameInput={{
        props: {
          id: "project-destination-name",
          autoFocus: true,
          value: newWorkspaceName,
          onChange: (e) => setNewWorkspaceName(e.target.value),
        },
      }}
      submitButton={{
        props: {
          disabled: !destination,
          onClick: () => destination && onSubmit(destination),
          children: selected.needsUpgrade
            ? "Upgrade and move"
            : isNewWorkspace
              ? "Create workspace and move"
              : "Move project",
        },
      }}
      cancelButton={{ props: { onClick: onCancel } }}
    />
  );
}

export const ProjectDestinationForm = React.forwardRef(ProjectDestinationForm_);
